// n8n сам на sudrf не ходит: Node/TLS там часто зависает на CONNECT.
// Валидируем вход и POST JSON на Python API (VPS), который ходит через proxy.market.
const API_URL = 'http://77.222.55.230:8080/delo';
const API_KEY = 'SET_COURT_KB_API_KEY';

const COURTS = {
  'sovetsky-vrn': true,
  'kominternovsky-vrn': true,
  'zheleznodorozhny-vrn': true,
  'levoberezhny-vrn': true,
  'centralny-vrn': true,
  'lensud-vrn': true,
};

const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const court_slug = String(body.court_slug || '').trim();
const case_number = String(body.case_number || '').trim();
const last_name = String(body.last_name || '').trim();
const production_type = String(body.production_type || 'civil_first_instance').trim();

if (!court_slug || !COURTS[court_slug]) {
  return [{ json: { skipHttp: true, status: 'error', result: `Неизвестный суд '${court_slug}'. Допустимые: ${Object.keys(COURTS).join(', ')}.` } }];
}
if (!case_number && !last_name) {
  return [{ json: { skipHttp: true, status: 'error', result: 'Нужно указать case_number или last_name.' } }];
}

return [{ json: {
  skipHttp: false,
  apiUrl: API_URL,
  apiKey: API_KEY,
  payload: {
    court_slug,
    case_number: case_number || null,
    last_name: last_name || null,
    production_type,
  },
} }];

const item = $input.first().json || {};
const nested = item.body && typeof item.body === 'object' ? item.body : item;
const status = nested.status || item.status;
const result = nested.result || item.result;
if (status && result) {
  return [{ json: { status, result } }];
}
if (nested.detail) {
  return [{ json: { status: 'error', result: String(nested.detail) } }];
}
const err = item.error && (item.error.message || item.error);
if (err) {
  return [{ json: { status: 'error', result: 'Сервис поиска дела временно недоступен (' + String(err) + '). Попробуйте ещё раз.' } }];
}
return [{ json: { status: 'error', result: 'Сервис поиска дела временно недоступен. Попробуйте задать вопрос ещё раз.' } }];
